import os
import re
from typing import Tuple

# File extensions / names to process
CODE_EXTENSIONS = {'.java', '.js', '.jsx', '.mjs', '.html', '.xml', '.css'}
CONFIG_EXTENSIONS = {'.yml', '.yaml'}
MARKUP_EXTENSIONS = {'.md'}  # remove HTML-style comments
SPECIAL_FILENAMES = {'Dockerfile'}

SKIP_DIRS = {'target', 'node_modules', '.git', '.idea'}

def strip_yaml(line: str) -> str:
    # Remove comments (#) not in quotes
    if '#' not in line:
        return line
    result = []
    in_single = False
    in_double = False
    for i, ch in enumerate(line):
        if ch == "'" and not in_double:
            in_single = not in_single
        elif ch == '"' and not in_single:
            in_double = not in_double
        if ch == '#' and not in_single and not in_double:
            # stop here, ignore rest
            break
        result.append(ch)
    return ''.join(result).rstrip() + ('\n' if line.endswith('\n') else '')

def strip_xml_html_comments(text: str) -> str:
    # Remove <!-- --> comments
    return re.sub(r'<!--.*?-->', '', text, flags=re.DOTALL)

def strip_block_and_line_comments(code: str, is_js: bool = False) -> str:
    """State machine to remove // and /* */ comments while preserving strings/template literals."""
    i = 0
    n = len(code)
    out = []
    in_sl_comment = False
    in_ml_comment = False
    in_single = False
    in_double = False
    in_backtick = False if is_js else False
    escape = False
    while i < n:
        ch = code[i]
        nxt = code[i+1] if i+1 < n else ''
        if in_sl_comment:
            if ch == '\n':
                in_sl_comment = False
                out.append(ch)
            i += 1
            continue
        if in_ml_comment:
            if ch == '*' and nxt == '/':
                in_ml_comment = False
                i += 2
            else:
                i += 1
            continue
        if in_single:
            out.append(ch)
            if not escape and ch == "'":
                in_single = False
            escape = (ch == '\\' and not escape)
            i += 1
            continue
        if in_double:
            out.append(ch)
            if not escape and ch == '"':
                in_double = False
            escape = (ch == '\\' and not escape)
            i += 1
            continue
        if is_js and in_backtick:
            out.append(ch)
            if ch == '`' and not escape:
                in_backtick = False
            escape = (ch == '\\' and not escape)
            i += 1
            continue
        # Not inside string/comment
        if ch == '/' and nxt == '/':
            in_sl_comment = True
            i += 2
            continue
        if ch == '/' and nxt == '*':
            in_ml_comment = True
            i += 2
            continue
        if ch == "'":
            in_single = True
            out.append(ch)
            escape = False
            i += 1
            continue
        if ch == '"':
            in_double = True
            out.append(ch)
            escape = False
            i += 1
            continue
        if is_js and ch == '`':
            in_backtick = True
            out.append(ch)
            escape = False
            i += 1
            continue
        out.append(ch)
        i += 1
    return ''.join(out)

def should_process(path: str) -> bool:
    base = os.path.basename(path)
    if base in SPECIAL_FILENAMES:
        return True
    ext = os.path.splitext(path)[1]
    return ext in CODE_EXTENSIONS | CONFIG_EXTENSIONS | MARKUP_EXTENSIONS

def process_file(path: str) -> Tuple[bool, str]:
    try:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            original = f.read()
    except Exception:
        return False, 'read_error'
    base = os.path.basename(path)
    ext = os.path.splitext(path)[1]
    updated = original
    if base == 'Dockerfile':
        # Remove lines starting with # and inline # after a space
        new_lines = []
        for line in original.splitlines(keepends=True):
            if line.lstrip().startswith('#'):
                continue
            if '#' in line:
                # crude inline removal only if preceded by space
                parts = line.split('#')
                if len(parts) > 1 and parts[0].endswith(' '):
                    line = parts[0].rstrip() + ('\n' if line.endswith('\n') else '')
            new_lines.append(line)
        updated = ''.join(new_lines)
    elif ext in CONFIG_EXTENSIONS:
        new_lines = []
        for line in original.splitlines(keepends=True):
            stripped = strip_yaml(line)
            if stripped.strip() == '':
                # keep blank line only if original had no non-comment content
                if line.strip().startswith('#'):
                    continue
            new_lines.append(stripped)
        updated = ''.join(new_lines)
    elif ext in {'.xml', '.html', '.md'}:
        updated = strip_xml_html_comments(original)
    elif ext in {'.java', '.js', '.jsx', '.mjs', '.css'}:
        is_js = ext in {'.js', '.jsx', '.mjs'}
        updated = strip_block_and_line_comments(original, is_js=is_js)
        # Also remove leading/trailing whitespace lines left by full-line comments
        updated_lines = []
        for ln in updated.splitlines(keepends=True):
            updated_lines.append(ln)
        updated = ''.join(updated_lines)
    if updated != original:
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write(updated)
            return True, 'modified'
        except Exception:
            return False, 'write_error'
    return False, 'unchanged'


def main():
    root = os.path.dirname(os.path.abspath(__file__))
    modified_count = 0
    processed = 0
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip unwanted dirs
        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS]
        for name in filenames:
            path = os.path.join(dirpath, name)
            if not should_process(path):
                continue
            ok, status = process_file(path)
            processed += 1
            if ok:
                modified_count += 1
    print(f"Processed {processed} files. Modified {modified_count} files.")

if __name__ == '__main__':
    main()
